        points[i].id = i + 1;
    }

    sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
        return tie(a.x, a.y) < tie(b.x, b.y);
    });

    string s;
    cin >> s;

    ll dx = 1, dy = 1;

    auto angleLess = [&](ll vx1, ll vy1, ll vx2, ll vy2) {
        i128 x1 = i128(vx1) * dx + i128(vy1) * dy;
        i128 y1 = i128(vx1) * dy - i128(vy1) * dx;
        i128 x2 = i128(vx2) * dx + i128(vy2) * dy;
        i128 y2 = i128(vx2) * dy - i128(vy2) * dx;

        auto category = [](i128 x, i128 y) {
            if (y < 0) return 0;
            if (y == 0 && x >= 0) return 1;
            if (y > 0) return 2;
            return 3;
        };

        int c1 = category(x1, y1);
        int c2 = category(x2, y2);

        if (c1 != c2) return c1 < c2;
        return i128(vx1) * vy2 - i128(vy1) * vx2 < 0;
    };

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        int best = i + 1;

        for (int j = i + 2; j < n; ++j) {
            ll bx = points[best].x - points[i].x;
            ll by = points[best].y - points[i].y;
