        ps[i].id = i + 1;
    }

    sort(ps.begin(), ps.end(), [](const Item& a, const Item& b) {
        return tie(a.p.x, a.p.y) < tie(b.p.x, b.p.y);
    });

    string s;
    cin >> s;

    Point lastDirection{1, 1};

    auto angleLess = [](const Point& a, const Point& b, const Point& direction) {
        const i128 dotA = i128(a.x) * direction.x + i128(a.y) * direction.y;
        const i128 dotB = i128(b.x) * direction.x + i128(b.y) * direction.y;
        const i128 sinA = i128(a.x) * direction.y - i128(a.y) * direction.x;
        const i128 sinB = i128(b.x) * direction.y - i128(b.y) * direction.x;

        const int halfA = (sinA < 0 || (sinA == 0 && dotA >= 0)) ? 0 : 1;
        const int halfB = (sinB < 0 || (sinB == 0 && dotB >= 0)) ? 0 : 1;

        if (halfA != halfB) return halfA < halfB;

        const i128 cross = i128(a.x) * b.y - i128(a.y) * b.x;
        return cross < 0;
    };

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        int best = i + 1;

        for (int j = i + 2; j < n; ++j) {
            const Point bestVector = ps[best].p - ps[i].p;
            const Point currentVector = ps[j].p - ps[i].p;

            if ((s[i] == 'L' &&
                 angleLess(bestVector, currentVector, lastDirection)) ||
                (s[i] != 'L' &&
                 angleLess(currentVector, bestVector, lastDirection))) {
                best = j;
            }
